do $$ begin
 if (select count(*) from private.bamco_banks where kind='routes' and deleted_at is null)<>(select count(*) from route_cleanup_plan)
 or exists(select 1 from route_cleanup_plan p left join private.bamco_banks b on b.kind='routes' and b.id=p.id and b.deleted_at is null where b.id is null or b.revision<>p.revision)
 then raise exception 'Route bank changed during review; stop and refresh'; end if;
end $$;
insert into private.bamco_route_cleanup_audit(batch,id,before_row,kept_id,category)
select '2026-11-23-exclusive-road-groups',b.id,to_jsonb(b),p.keep,p.category from private.bamco_banks b join route_cleanup_plan p on p.id=b.id where b.kind='routes';
update private.bamco_banks b set deleted_at=now(),definition=jsonb_set(b.definition,'{active}','false'),revision=b.revision+1,updated_at=now()
from route_cleanup_plan p where b.kind='routes' and b.id=p.id and p.id<>p.keep;
update private.bamco_banks b set definition=jsonb_set(b.definition,'{routeId}',to_jsonb(p.category)),revision=b.revision+1,updated_at=now()
from route_cleanup_plan p where b.kind='routes' and b.id=p.id and p.id=p.keep and p.category in ('rural','hot','mountain') and b.definition->>'routeId'<>p.category;
do $$ begin
 if exists(select 1 from private.bamco_banks where kind='routes' and deleted_at is null and definition->>'routeId' in ('rural','hot','mountain')
 group by least(private.bamco_route_city_key(definition->>'origin'),private.bamco_route_city_key(definition->>'destination')),greatest(private.bamco_route_city_key(definition->>'origin'),private.bamco_route_city_key(definition->>'destination')) having count(*)>1)
 then raise exception 'Duplicate paved route remains'; end if;
 if exists(select 1 from private.bamco_route_cleanup_audit a join private.bamco_banks b on b.kind='routes' and b.id=a.id
 where a.batch='2026-11-23-exclusive-road-groups' and a.category in ('urban','offroad') and a.before_row<>to_jsonb(b))
 then raise exception 'An urban or off-road row changed'; end if;
end $$;
